head.script:
scwin.onpageload = function () {
    let arr = [
        { "txt" : "김철수", "ccb" : "A" },
        { "txt" : "이영희", "ccb" : "B" }
    ];
    dlt_a.setJSON(arr);
    dlt_b.setJSON(arr);

    // 이동 키 입력 감지 (capture 단계)
    grd_a.render.addEventListener("keydown", function (e) { scwin.keyCapture(e, grd_a, "A"); }, true);
    grd_b.render.addEventListener("keydown", function (e) { scwin.keyCapture(e, grd_b, "B"); }, true);
};

// 이동 키 이름
scwin.keyName = { 35 : "End", 39 : "Right", 9 : "Tab" };

// 이동 키 입력 -> 300ms 후 그리드 포커스 Column 과 실제 포커스 위치 출력
scwin.keyCapture = function (e, grd, name) {
    let key = scwin.keyName[e.keyCode];
    if (!key || e.shiftKey) {
        return;
    }
    let beforeCol = grd.getFocusedColumnID();
    setTimeout(function () {
        scwin.setReturnValue("[" + name + "] " + beforeCol + " " + key + " -> 포커스 Column : " + grd.getFocusedColumnID() + " / 실제 포커스 : " + scwin.getActiveInfo(grd));
    }, 300);
};

// 실제 포커스(document.activeElement) 위치
scwin.getActiveInfo = function (grd) {
    let el = document.activeElement;
    let td = el ? el.closest("td[id*='_cell_']") : null;
    if (!td || !grd.render.contains(td)) {
        return "그리드 밖";
    }
    let pos = td.id.split("_cell_")[1].split("_");
    let colId = grd.getColumnID(Number(pos[1]));
    return colId + " Row " + pos[0] + (el.tagName === "INPUT" ? " 입력창" : " Cell");
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
